 void xtream(){LinearLayout fields=new LinearLayout(this);fields.setOrientation(1);EditText server=new EditText(this),user=new EditText(this),pass=new EditText(this);server.setHint("https://server:port");user.setHint("Логин");pass.setHint("Пароль");pass.setInputType(129);for(EditText e:new EditText[]{server,user,pass}){e.setSingleLine();fields.addView(e);}new AlertDialog.Builder(this).setTitle("Xtream Codes").setView(fields).setPositiveButton("Подключить",(d,w)->{String base=server.getText().toString().trim().replaceAll("/+$","");String credentials="username="+android.net.Uri.encode(user.getText().toString())+"&password="+android.net.Uri.encode(pass.getText().toString());prefs.edit().putString("xcBase",base).putString("xcAuth",credentials).putString("xcUser",android.net.Uri.encode(user.getText().toString())).putString("xcPass",android.net.Uri.encode(pass.getText().toString())).apply();load(base+"/get.php?"+credentials+"&type=m3u_plus&output=ts");}).setNegativeButton("Отмена",null).show();}
 void pickPlaylist(){android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(android.content.Intent.CATEGORY_OPENABLE);intent.setType("*/*");try{startActivityForResult(intent,301);}catch(android.content.ActivityNotFoundException e){Toast.makeText(this,"На устройстве нет файлового менеджера",Toast.LENGTH_LONG).show();}}
 @Override protected void onActivityResult(int request,int result,android.content.Intent data){super.onActivityResult(request,result,data);if(request==601||request==602){if(result==RESULT_OK&&data!=null&&data.getData()!=null){if(request==601){current=null;player.setMediaItem(MediaItem.fromUri(data.getData()));player.prepare();player.play();status.setText("Локальное видео");}else exportRecording(data.getData());}else pendingExport=null;return;}if(request==501||request==502){if(result==RESULT_OK&&data!=null){ArrayList<String> words=data.getStringArrayListExtra(android.speech.RecognizerIntent.EXTRA_RESULTS);if(words!=null&&!words.isEmpty()){if(request==502)voiceSearch(words.get(0));else voiceCommand(words.get(0));}}return;}if(request==401||request==402){if(result==RESULT_OK&&data!=null&&data.getData()!=null)backupFile(request,data.getData());return;}if(request!=301||result!=RESULT_OK||data==null||data.getData()==null)return;android.net.Uri uri=data.getData();status.setText("Чтение плейлиста…");new Thread(()->{try(InputStream in=getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Empty file");StringBuilder s=new StringBuilder();try(BufferedReader reader=new BufferedReader(new InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=reader.readLine())!=null){s.append(line).append('\n');if(s.length()>20000000)throw new IOException("File too large");}}String playlist=s.toString();runOnUiThread(()->{if(!playlist.contains("#EXTINF")){status.setText("Неверный формат M3U");return;}savePlaylist(playlist);group="";filter="";onlyFav=false;parse(playlist);render();status.setText("Каналов: "+channels.size());});}catch(Exception e){runOnUiThread(()->status.setText("Не удалось прочитать файл плейлиста"));}}).start();}
 void add(){EditText e=new EditText(this);e.setSingleLine();e.setHint("https://.../playlist.m3u");new AlertDialog.Builder(this).setTitle("Адрес плейлиста").setView(e).setPositiveButton("Загрузить",(d,w)->load(e.getText().toString().trim())).setNegativeButton("Отмена",null).show();}
 void load(String url){load(url,false);} void load(String url,boolean refresh){final String sourceKey=prefs.getString("activeSource","");status.setText("Загрузка…");new Thread(()->{try{URL u=new URL(url);if(!u.getProtocol().equals("https")&&!u.getProtocol().equals("http"))throw new IOException("HTTP(S) only");URLConnection c=u.openConnection();c.setConnectTimeout(15000);c.setReadTimeout(20000);StringBuilder s=new StringBuilder();try(BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream(),java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){s.append(line).append('\n');if(s.length()>20000000)throw new IOException("Playlist too large");}}String data=s.toString();runOnUiThread(()->{if(!data.contains("#EXTINF")){status.setText("Не найден список каналов M3U");return;}if(refresh){String key=sourceKey;if(!key.equals(prefs.getString("activeSource","")))return;android.content.SharedPreferences.Editor ed=prefs.edit().putString("playlist",data);if(!key.isEmpty())ed.putString(key,data);ed.apply();}else{savePlaylist(data);prefs.edit().putString("url_"+prefs.getString("activeSource",""),url).apply();}group="";filter="";parse(data);render();prefs.edit().putLong("updated_"+prefs.getString("activeSource",""),System.currentTimeMillis()).apply();status.setText("Каналов: "+channels.size());});}catch(Exception ex){runOnUiThread(()->status.setText("Ошибка загрузки плейлиста"));}}).start();}
 void savePlaylist(String data){String header=data.split("\\r?\\n",2)[0];String guideUrl=attribute(header,"url-tvg");if(guideUrl.isEmpty())guideUrl=attribute(header,"x-tvg-url");if(guideUrl.startsWith("http://")||guideUrl.startsWith("https://"))loadEpg(guideUrl);String key="p_"+UUID.randomUUID().toString();prefs.edit().putString(key,data).putString("activeSource",key).putString("playlist",data).apply();try{org.json.JSONArray a=new org.json.JSONArray(prefs.getString("sources","[]"));org.json.JSONObject o=new org.json.JSONObject();o.put("key",key);o.put("name","Плейлист "+(a.length()+1));a.put(o);prefs.edit().putString("sources",a.toString()).apply();}catch(Exception ignored){}}
 void playlistManager(){try{org.json.JSONArray a=new org.json.JSONArray(prefs.getString("sources","[]"));String[] names=new String[a.length()];for(int i=0;i<a.length();i++)names[i]=a.getJSONObject(i).getString("name");new AlertDialog.Builder(this).setTitle("Мои плейлисты").setItems(names,(d,i)->{try{org.json.JSONObject o=a.getJSONObject(i);new AlertDialog.Builder(this).setTitle(o.getString("name")).setItems(new String[]{"Открыть","Переименовать","Удалить"},(x,j)->{try{String key=o.getString("key");if(j==0){String data=prefs.getString(key,"");prefs.edit().putString("activeSource",key).putString("playlist",data).apply();group="";filter="";onlyFav=false;parse(data);render();}else if(j==1){EditText e=new EditText(this);e.setText(o.optString("name"));new AlertDialog.Builder(this).setView(e).setPositiveButton("Сохранить",(q,z)->{try{o.put("name",e.getText().toString());prefs.edit().putString("sources",a.toString()).apply();}catch(Exception ignored){}}).show();}else{a.remove(i);prefs.edit().remove(key).putString("sources",a.toString()).apply();}}catch(Exception ignored){}}).show();}catch(Exception ignored){}}).setNegativeButton("Закрыть",null).show();}catch(Exception ignored){}}
 String attribute(String line,String key){java.util.regex.Matcher m=java.util.regex.Pattern.compile("(?:^|\\s)"+java.util.regex.Pattern.quote(key)+"=\"([^\"]*)\"").matcher(line);return m.find()?m.group(1):"";}
 void archive(Channel ch,Epg.Programme p){if(locked(ch.group)){askPin(()->archiveAllowed(ch,p));return;}archiveAllowed(ch,p);} void archiveAllowed(Channel ch,Epg.Programme p){long now=System.currentTimeMillis();if(p.start>=now||ch.catchupDays<=0||now-p.start>ch.catchupDays*86400000L){Toast.makeText(this,"Архив недоступен для этой передачи",Toast.LENGTH_LONG).show();return;}String template=ch.catchupSource.isEmpty()?prefs.getString("archiveTemplate_"+prefs.getString("activeSource",""),""):ch.catchupSource;if(template.isEmpty()){archiveSettings();return;}String u=template.replace("{url}",ch.url).replace("{utc}",Long.toString(p.start/1000)).replace("{utcend}",Long.toString(p.end/1000)).replace("{duration}",Long.toString((p.end-p.start)/1000)).replace("{lutc}",Long.toString(now/1000)).replace("{start}",Long.toString(p.start/1000)).replace("{end}",Long.toString(p.end/1000));if(!ch.catchupSource.isEmpty()&&ch.catchup.equals("append"))u=ch.url+u;if(!u.startsWith("http://")&&!u.startsWith("https://")||u.contains("{")){Toast.makeText(this,"Неподдерживаемый формат архива",Toast.LENGTH_LONG).show();return;}current=ch;status.setText("Архив • "+p.title);player.setMediaItem(MediaItem.fromUri(u));player.prepare();player.play();}
 void archiveSettings(){String key="archiveTemplate_"+prefs.getString("activeSource","");EditText input=new EditText(this);input.setText(prefs.getString(key,""));input.setHint("{url}&start={utc}&end={utcend}");new AlertDialog.Builder(this).setTitle("Формат архивной ссылки").setMessage("Введите шаблон, предоставленный оператором IPTV. {url} — исходный поток; {utc}, {utcend} — начало и конец в секундах Unix; {duration} — длительность. Пример в поле не является подтверждённым форматом вашего оператора.").setView(input).setPositiveButton("Сохранить",(d,w)->prefs.edit().putString(key,input.getText().toString().trim()).apply()).setNegativeButton("Отмена",null).show();}
 void parse(String data){channels.clear();String name="",g="",id="",logo="",catchup="",source="";int days=0;for(String raw:data.split("\\r?\\n")){String l=raw.trim();if(l.startsWith("#EXTINF")){int comma=l.indexOf(',');name=comma>=0?l.substring(comma+1):"Канал";java.util.regex.Matcher m=java.util.regex.Pattern.compile("group-title=\"([^\"]*)\"").matcher(l);g=m.find()?m.group(1):"Без группы";java.util.regex.Matcher t=java.util.regex.Pattern.compile("tvg-id=\"([^\"]*)\"").matcher(l);id=t.find()?t.group(1):"";logo=attribute(l,"tvg-logo");catchup=attribute(l,"catchup");source=attribute(l,"catchup-source");try{String retention=attribute(l,"catchup-days");if(retention.isEmpty())retention=attribute(l,"tvg-rec");days=Integer.parseInt(retention);}catch(Exception e){days=0;}}else if(l.startsWith("#EXTGRP:")){g=l.substring(8).trim();}else if(l.startsWith("http://")||l.startsWith("https://")){Channel ch=new Channel(name.isEmpty()?l:name,l,g);ch.id=id;ch.logo=logo;logo="";ch.catchup=catchup;ch.catchupSource=source;ch.catchupDays=days;channels.add(ch);catchup="";source="";days=0;id="";name="";g="";}}}
 void render(){displayed.clear();ArrayList<String> labels=new ArrayList<>();for(Channel c:channels){if(onlyFav&&!favorites.contains(c.url)||!group.isEmpty()&&!group.equals(c.group)||!c.name.toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT)))continue;displayed.add(c);Epg.Programme p=epg.current(c.id);labels.add((favorites.contains(c.url)?"★ ":"")+c.name+(p==null?"":"\n"+p.title));}list.setAdapter(new ChannelAdapter());}
 class ChannelAdapter extends BaseAdapter {
 public int getCount(){return displayed.size();}public Object getItem(int i){return displayed.get(i);}public long getItemId(int i){return i;}
 public View getView(int i,View recycled,android.view.ViewGroup parent){LinearLayout row;ImageView image;TextView name,programme;if(recycled==null){row=new LinearLayout(MainActivity.this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(8),dp(5),dp(8),dp(5));image=new ImageView(MainActivity.this);image.setScaleType(ImageView.ScaleType.FIT_CENTER);row.addView(image,new LinearLayout.LayoutParams(dp(44),dp(36)));LinearLayout texts=new LinearLayout(MainActivity.this);texts.setOrientation(1);texts.setPadding(dp(9),0,0,0);row.addView(texts,new LinearLayout.LayoutParams(0,-2,1));name=new TextView(MainActivity.this);name.setTextColor(0xffeff5fc);name.setTextSize(fontSize());name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);texts.addView(name);programme=new TextView(MainActivity.this);programme.setTextColor(0xffa2b4c8);programme.setTextSize(fontSize()-3);programme.setSingleLine(true);programme.setEllipsize(android.text.TextUtils.TruncateAt.END);texts.addView(programme);row.setTag(new Object[]{image,name,programme});}else{row=(LinearLayout)recycled;Object[] views=(Object[])row.getTag();image=(ImageView)views[0];name=(TextView)views[1];programme=(TextView)views[2];}Channel ch=displayed.get(i);name.setText((prefs.getBoolean("showNumbers",true)?(channels.indexOf(ch)+1)+". ":"")+(favorites.contains(ch.url)?"★ ":"")+ch.name);Epg.Programme p=epg.current(ch.id);programme.setText(locked(ch.group)?"Заблокировано":(ch.catchupDays>0?"↶ "+ch.catchupDays+" дн. • ":"")+(p==null?ch.group:p.title));image.setVisibility(prefs.getBoolean("showLogos",true)?View.VISIBLE:View.GONE);programme.setVisibility(prefs.getBoolean("showProgramme",true)?View.VISIBLE:View.GONE);if(image.getVisibility()==View.VISIBLE)logos.bind(image,ch.logo);else logos.bind(image,"");return row;}
 }
 void play(Channel c){if(locked(c.group)){askPin(()->playAllowed(c));return;}playAllowed(c);} void playAllowed(Channel c){current=c;remember(c);Epg.Programme p=epg.current(c.id);status.setText(c.name+(p==null?"":" • "+p.title));player.setMediaItem(MediaItem.fromUri(c.url));player.prepare();player.play();video.requestFocus();}
 void playbackSettings(){String[] labels={"Аудиодорожка","Субтитры","Масштаб изображения","Скорость воспроизведения","Внешний плеер"};new AlertDialog.Builder(this).setTitle("Воспроизведение").setItems(labels,(d,i)->{if(i==0)tracks(androidx.media3.common.C.TRACK_TYPE_AUDIO);else if(i==1)tracks(androidx.media3.common.C.TRACK_TYPE_TEXT);else if(i==2)new AlertDialog.Builder(this).setItems(new String[]{"По размеру","Заполнить","Увеличить"},(x,j)->video.setResizeMode(new int[]{0,3,4}[j])).show();else if(i==3)new AlertDialog.Builder(this).setItems(new String[]{"0.75x","1x","1.25x","1.5x","2x"},(x,j)->player.setPlaybackSpeed(new float[]{.75f,1f,1.25f,1.5f,2f}[j])).show();else if(current!=null){try{android.content.Intent intent=new android.content.Intent(android.content.Intent.ACTION_VIEW);intent.setDataAndType(android.net.Uri.parse(current.url),"video/*");startActivity(android.content.Intent.createChooser(intent,"Внешний плеер"));}catch(Exception e){Toast.makeText(this,"Нет внешнего плеера",Toast.LENGTH_SHORT).show();}}}).show();}
 void tracks(int type){ArrayList<String> labels=new ArrayList<>();ArrayList<androidx.media3.common.TrackSelectionOverride> overrides=new ArrayList<>();labels.add("Автоматически");overrides.add(null);if(type==androidx.media3.common.C.TRACK_TYPE_TEXT){labels.add("Отключить");overrides.add(null);}for(androidx.media3.common.Tracks.Group g:player.getCurrentTracks().getGroups()){if(g.getType()!=type)continue;for(int i=0;i<g.length;i++){if(!g.isTrackSupported(i))continue;androidx.media3.common.Format f=g.getTrackFormat(i);labels.add((f.label==null?"Дорожка "+(i+1):f.label)+(f.language==null?"":" • "+f.language));overrides.add(new androidx.media3.common.TrackSelectionOverride(g.getMediaTrackGroup(),i));}}new AlertDialog.Builder(this).setItems(labels.toArray(new String[0]),(d,i)->{androidx.media3.common.TrackSelectionParameters.Builder b=player.getTrackSelectionParameters().buildUpon().clearOverridesOfType(type).setTrackTypeDisabled(type,type==androidx.media3.common.C.TRACK_TYPE_TEXT&&i==1);if(overrides.get(i)!=null)b.addOverride(overrides.get(i));player.setTrackSelectionParameters(b.build());}).show();}
 void multiView(){if(displayed.size()<2){Toast.makeText(this,"Нужно минимум два канала",Toast.LENGTH_SHORT).show();return;}String[] names=new String[displayed.size()];boolean[] checked=new boolean[names.length];ArrayList<Channel> options=new ArrayList<>(displayed);for(int i=0;i<names.length;i++)names[i]=options.get(i).name;new AlertDialog.Builder(this).setTitle("Выберите 2–4 канала").setMultiChoiceItems(names,checked,(d,i,b)->checked[i]=b).setPositiveButton("Открыть",(d,w)->{ArrayList<Channel> selected=new ArrayList<>();for(int i=0;i<checked.length;i++)if(checked[i])selected.add(options.get(i));if(selected.size()<2||selected.size()>4){Toast.makeText(this,"Выберите от двух до четырёх каналов",Toast.LENGTH_SHORT).show();return;}showMulti(selected);}).setNegativeButton("Отмена",null).show();}
 void showMulti(ArrayList<Channel> selected){for(Channel ch:selected)if(locked(ch.group)){askPin(()->showMultiAllowed(selected));return;}showMultiAllowed(selected);} void showMultiAllowed(ArrayList<Channel> selected){boolean resume=player.isPlaying();player.pause();ArrayList<ExoPlayer> players=new ArrayList<>();LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);Dialog dialog=new Dialog(this,android.R.style.Theme_Material_NoActionBar);dialog.setContentView(panel);dialog.setOnDismissListener(d->{for(ExoPlayer p:players)p.release();if(resume&&!isFinishing())player.play();});for(int i=0;i<selected.size();i+=2){LinearLayout row=new LinearLayout(this);panel.addView(row,new LinearLayout.LayoutParams(-1,0,1));for(int j=i;j<Math.min(i+2,selected.size());j++){Channel ch=selected.get(j);LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);row.addView(tile,new LinearLayout.LayoutParams(0,-1,1));ExoPlayer p=new ExoPlayer.Builder(this).build();players.add(p);PlayerView pv=new PlayerView(this);pv.setUseController(false);pv.setPlayer(p);tile.addView(pv,new LinearLayout.LayoutParams(-1,0,1));Button audio=new Button(this);audio.setText(ch.name+" • Звук");tile.addView(audio);audio.setOnClickListener(v->{for(ExoPlayer other:players)other.setVolume(other==p?1f:0f);});p.setVolume(j==0?1f:0f);p.setMediaItem(MediaItem.fromUri(ch.url));p.prepare();p.play();}}Button close=new Button(this);close.setText("Закрыть мультиэкран");close.setOnClickListener(v->dialog.dismiss());panel.addView(close);dialog.show();dialog.getWindow().setLayout(-1,-1);}
 File recordingDir(){File dir=new File(getFilesDir(),"recordings");dir.mkdirs();return dir;}
 void record(){if(recorder.worker!=null){recorder.stop();status.setText("Остановка записи…");return;}if(current==null){Toast.makeText(this,"Выберите канал",Toast.LENGTH_SHORT).show();return;}File file=new File(recordingDir(),System.currentTimeMillis()+".ts");if(recorder.start(current.url,file,()->runOnUiThread(()->{if(!isFinishing()&&!isDestroyed())status.setText(recordingResult(file));})))status.setText("Запись • "+current.name);}
 String recordingResult(File file){String error=recorder.lastError;if(!error.isEmpty())return (file.length()>0?"Частичная запись сохранена: ":"Запись не удалась: ")+error;return file.length()>0?"Запись сохранена":"Запись не создана";}
 void recordings(){File[] files=recordingDir().listFiles((dir,name)->name.endsWith(".ts"));if(files==null||files.length==0){Toast.makeText(this,"Нет записей",Toast.LENGTH_SHORT).show();return;}Arrays.sort(files,(a,b)->Long.compare(b.lastModified(),a.lastModified()));String[] labels=new String[files.length];for(int i=0;i<files.length;i++)labels[i]=new java.text.SimpleDateFormat("dd.MM.yyyy HH:mm",Locale.getDefault()).format(new Date(files[i].lastModified()))+" • "+files[i].length()/1048576+" МБ";new AlertDialog.Builder(this).setTitle("Мои записи").setItems(labels,(d,i)->new AlertDialog.Builder(this).setItems(new String[]{"Воспроизвести","Удалить","Экспорт на накопитель","Экспорт в SMB / NAS"},(x,j)->{if(recorder.running){Toast.makeText(this,"Сначала остановите запись",Toast.LENGTH_SHORT).show();return;}if(j==3){smbDialog(files[i]);return;}if(j==2){chooseExport(files[i]);return;}if(j==0){current=null;player.setMediaItem(MediaItem.fromUri(android.net.Uri.fromFile(files[i])));player.prepare();player.play();status.setText("Запись • "+labels[i]);}else new AlertDialog.Builder(this).setMessage("Удалить запись?").setPositiveButton("Удалить",(q,z)->{files[i].delete();recordings();}).setNegativeButton("Отмена",null).show();}).show()).show();}
 File pendingExport;
 void localVideo(){android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_OPEN_DOCUMENT);i.addCategory(android.content.Intent.CATEGORY_OPENABLE);i.setType("video/*");try{startActivityForResult(i,601);}catch(android.content.ActivityNotFoundException e){Toast.makeText(this,"Файловый менеджер недоступен",Toast.LENGTH_LONG).show();}}
 void chooseExport(File file){pendingExport=file;android.content.Intent i=new android.content.Intent(android.content.Intent.ACTION_CREATE_DOCUMENT);i.addCategory(android.content.Intent.CATEGORY_OPENABLE);i.setType("video/mp2t");i.putExtra(android.content.Intent.EXTRA_TITLE,file.getName());try{startActivityForResult(i,602);}catch(Exception e){pendingExport=null;Toast.makeText(this,"Файловый менеджер недоступен",Toast.LENGTH_LONG).show();}}
 void exportRecording(android.net.Uri uri){File source=pendingExport;pendingExport=null;if(source==null||!source.isFile())return;status.setText("Копирование записи…");new Thread(()->{try(InputStream in=new FileInputStream(source);OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)out.write(b,0,n);out.flush();runOnUiThread(()->status.setText("Запись экспортирована"));}catch(Exception e){runOnUiThread(()->status.setText("Ошибка экспорта записи"));}}).start();}
 void smbDialog(File source){LinearLayout fields=new LinearLayout(this);fields.setOrientation(1);EditText address=new EditText(this),user=new EditText(this),password=new EditText(this);address.setHint("smb://192.168.1.10/Video/file.mp4");user.setHint("Пользователь (пусто — гость)");password.setHint("Пароль");password.setInputType(129);for(EditText e:new EditText[]{address,user,password}){e.setSingleLine();fields.addView(e);}new AlertDialog.Builder(this).setTitle(source==null?"Видео с SMB / NAS":"Экспорт записи в SMB").setView(fields).setPositiveButton(source==null?"Открыть":"Копировать",(d,w)->{String url=address.getText().toString().trim(),login=user.getText().toString(),secret=password.getText().toString();if(!url.startsWith("smb://")||url.contains("@")){status.setText("Введите SMB-адрес без логина и пароля");return;}status.setText("Передача файла SMB…");new Thread(()->{File temp=null;try{if(source!=null){SmbStorage.upload(url,login,secret,source);runOnUiThread(()->status.setText("Запись экспортирована в SMB"));}else{long limit=Math.min(536870912L,getCacheDir().getUsableSpace()/2);temp=File.createTempFile("smb_",".video",getCacheDir());SmbStorage.download(url,login,secret,temp,limit);File ready=temp;runOnUiThread(()->{if(isDestroyed()){ready.delete();return;}current=null;player.setMediaItem(MediaItem.fromUri(android.net.Uri.fromFile(ready)));player.prepare();player.play();status.setText("Видео SMB");});}}catch(Exception e){if(temp!=null)temp.delete();runOnUiThread(()->status.setText("Ошибка SMB: проверьте адрес, доступ и размер файла"));}}).start();}).setNegativeButton("Отмена",null).show();}
 void timeshift(){new AlertDialog.Builder(this).setTitle("Управление эфиром").setItems(new String[]{"Пауза / продолжить","Назад 30 секунд","Вперёд 30 секунд","К прямому эфиру"},(d,i)->{if(i==0){if(player.isPlaying())player.pause();else player.play();return;}if(!player.isCurrentMediaItemSeekable()){Toast.makeText(this,"Источник не поддерживает перемотку",Toast.LENGTH_LONG).show();return;}if(i==1)player.seekTo(Math.max(0,player.getCurrentPosition()-30000));else if(i==2)player.seekTo(player.getCurrentPosition()+30000);else player.seekToDefaultPosition();}).show();}
 void vodMenu(){if(prefs.getString("xcBase","").isEmpty()){Toast.makeText(this,"Подключите Xtream Codes",Toast.LENGTH_LONG).show();return;}new AlertDialog.Builder(this).setTitle("Видеотека Xtream").setItems(new String[]{"Фильмы","Сериалы"},(d,i)->vodCategories(i==1)).show();}
 interface JsonResult{void accept(Object value)throws Exception;}
 void xcRequest(String action,JsonResult result){String base=prefs.getString("xcBase",""),auth=prefs.getString("xcAuth","");status.setText("Загрузка видеотеки…");new Thread(()->{try{URL u=new URL(base+"/player_api.php?"+auth+"&action="+action);URLConnection conn=u.openConnection();conn.setConnectTimeout(15000);conn.setReadTimeout(20000);StringBuilder s=new StringBuilder();try(BufferedReader reader=new BufferedReader(new InputStreamReader(conn.getInputStream(),java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=reader.readLine())!=null){s.append(line);if(s.length()>20000000)throw new IOException("Too large");}}Object value=new org.json.JSONTokener(s.toString()).nextValue();runOnUiThread(()->{try{result.accept(value);status.setText("Видеотека");}catch(Exception e){status.setText("Неверный ответ видеотеки");}});}catch(Exception e){runOnUiThread(()->status.setText("Ошибка загрузки видеотеки"));}}).start();}
 void vodCategories(boolean series){xcRequest(series?"get_series_categories":"get_vod_categories",value->{org.json.JSONArray a=(org.json.JSONArray)value;String[] names=new String[a.length()];for(int i=0;i<a.length();i++)names[i]=a.getJSONObject(i).optString("category_name");new AlertDialog.Builder(this).setTitle("Категории").setItems(names,(d,i)->{org.json.JSONObject o=a.optJSONObject(i);if(o!=null)vodList(series,o.optString("category_id"));}).show();});}
 void vodList(boolean series,String category){xcRequest((series?"get_series":"get_vod_streams")+"&category_id="+android.net.Uri.encode(category),value->{org.json.JSONArray a=(org.json.JSONArray)value;String[] names=new String[a.length()];for(int i=0;i<a.length();i++)names[i]=a.getJSONObject(i).optString("name");new AlertDialog.Builder(this).setTitle(series?"Сериалы":"Фильмы").setItems(names,(d,i)->{org.json.JSONObject o=a.optJSONObject(i);if(o==null)return;if(series)episodes(o.optString("series_id"));else playVod("movie",o.optString("stream_id"),o.optString("container_extension","mp4"),names[i]);}).show();});}
 void episodes(String id){xcRequest("get_series_info&series_id="+android.net.Uri.encode(id),value->{org.json.JSONObject seasons=((org.json.JSONObject)value).getJSONObject("episodes");ArrayList<org.json.JSONObject> items=new ArrayList<>();ArrayList<String> names=new ArrayList<>();Iterator<String> keys=seasons.keys();while(keys.hasNext()){String season=keys.next();org.json.JSONArray a=seasons.optJSONArray(season);if(a==null)continue;for(int i=0;i<a.length();i++){org.json.JSONObject o=a.optJSONObject(i);if(o==null)continue;items.add(o);names.add("Сезон "+season+" • "+o.optString("title"));}}new AlertDialog.Builder(this).setTitle("Эпизоды").setItems(names.toArray(new String[0]),(d,i)->{org.json.JSONObject o=items.get(i);playVod("series",o.optString("id"),o.optString("container_extension","mp4"),names.get(i));}).show();});}
 void playVod(String type,String id,String ext,String name){String u=prefs.getString("xcBase","")+"/"+type+"/"+prefs.getString("xcUser","")+"/"+prefs.getString("xcPass","")+"/"+android.net.Uri.encode(id)+"."+android.net.Uri.encode(ext);current=null;status.setText(name);player.setMediaItem(MediaItem.fromUri(u));player.prepare();player.play();}
 boolean locked(String group){return !prefs.getString("pinHash","").isEmpty()&&prefs.getStringSet("lockedGroups",Collections.emptySet()).contains(group);}
 String pinHash(String pin){try{byte[] bytes=java.security.MessageDigest.getInstance("SHA-256").digest((prefs.getString("pinSalt","")+pin).getBytes(java.nio.charset.StandardCharsets.UTF_8));return android.util.Base64.encodeToString(bytes,android.util.Base64.NO_WRAP);}catch(Exception e){throw new IllegalStateException(e);}}
 void askPin(Runnable action){EditText e=new EditText(this);e.setInputType(18);new AlertDialog.Builder(this).setTitle("Введите PIN").setView(e).setPositiveButton("OK",(d,w)->{if(pinHash(e.getText().toString()).equals(prefs.getString("pinHash","")))action.run();else Toast.makeText(this,"Неверный PIN",Toast.LENGTH_SHORT).show();}).setNegativeButton("Отмена",null).show();}
 void parental(){if(prefs.getString("pinHash","").isEmpty())setPin();else askPin(()->new AlertDialog.Builder(this).setTitle("Родительский контроль").setItems(new String[]{"Заблокировать группы","Изменить PIN","Отключить"},(d,i)->{if(i==0)lockGroups();else if(i==1)setPin();else prefs.edit().remove("pinHash").remove("lockedGroups").apply();}).show());}
 void setPin(){EditText e=new EditText(this);e.setInputType(18);new AlertDialog.Builder(this).setTitle("Новый PIN (4–8 цифр)").setView(e).setPositiveButton("Сохранить",(d,w)->{String pin=e.getText().toString();if(!pin.matches("[0-9]{4,8}")){Toast.makeText(this,"Нужно 4–8 цифр",Toast.LENGTH_SHORT).show();return;}prefs.edit().putString("pinSalt",UUID.randomUUID().toString()).apply();prefs.edit().putString("pinHash",pinHash(pin)).apply();lockGroups();}).setNegativeButton("Отмена",null).show();}
 void lockGroups(){TreeSet<String> groups=new TreeSet<>();for(Channel c:channels)groups.add(c.group);String[] names=groups.toArray(new String[0]);Set<String> selected=new HashSet<>(prefs.getStringSet("lockedGroups",Collections.emptySet()));boolean[] checks=new boolean[names.length];for(int i=0;i<names.length;i++)checks[i]=selected.contains(names[i]);new AlertDialog.Builder(this).setTitle("Закрытые группы").setMultiChoiceItems(names,checks,(d,i,b)->{if(b)selected.add(names[i]);else selected.remove(names[i]);}).setPositiveButton("Сохранить",(d,w)->prefs.edit().putStringSet("lockedGroups",selected).apply()).setNegativeButton("Отмена",null).show();}
 void backupMenu(){Runnable open=()->new AlertDialog.Builder(this).setTitle("Резервная копия").setMessage("Файл содержит адреса плейлистов и данные подключения. Храните его в безопасном месте.").setItems(new String[]{"Экспорт","Восстановление"},(d,i)->{android.content.Intent intent=new android.content.Intent(i==0?android.content.Intent.ACTION_CREATE_DOCUMENT:android.content.Intent.ACTION_OPEN_DOCUMENT);intent.addCategory(android.content.Intent.CATEGORY_OPENABLE);intent.setType("application/json");if(i==0)intent.putExtra(android.content.Intent.EXTRA_TITLE,"vision-backup.json");try{startActivityForResult(intent,401+i);}catch(Exception e){status.setText("Файловый менеджер недоступен");}}).show();if(!prefs.getString("pinHash","").isEmpty())askPin(open);else open.run();}
 void backupFile(int request,android.net.Uri uri){if(request==401){new Thread(()->{try{org.json.JSONObject root=new org.json.JSONObject();root.put("version",1);org.json.JSONObject values=new org.json.JSONObject();for(Map.Entry<String,?> e:prefs.getAll().entrySet()){Object v=e.getValue();if(v instanceof Set)values.put(e.getKey(),new org.json.JSONArray((Set<?>)v));else values.put(e.getKey(),v);}root.put("settings",values);try(OutputStream out=getContentResolver().openOutputStream(uri,"wt")){if(out==null)throw new IOException();out.write(root.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8));}runOnUiThread(()->status.setText("Резервная копия сохранена"));}catch(Exception e){runOnUiThread(()->status.setText("Ошибка экспорта"));}}).start();return;}new AlertDialog.Builder(this).setMessage("Заменить текущие настройки и плейлисты?").setPositiveButton("Восстановить",(d,w)->new Thread(()->{try{StringBuilder s=new StringBuilder();try(InputStream in=getContentResolver().openInputStream(uri);Reader reader=new InputStreamReader(in,java.nio.charset.StandardCharsets.UTF_8)){char[] b=new char[8192];int n;while((n=reader.read(b))!=-1){s.append(b,0,n);if(s.length()>100000000)throw new IOException();}}org.json.JSONObject root=new org.json.JSONObject(s.toString());if(root.getInt("version")!=1)throw new IOException();org.json.JSONObject values=root.getJSONObject("settings");android.content.SharedPreferences.Editor editor=prefs.edit().clear();Iterator<String> keys=values.keys();while(keys.hasNext()){String k=keys.next();Object v=values.get(k);if(v instanceof String)editor.putString(k,(String)v);else if(v instanceof Boolean)editor.putBoolean(k,(Boolean)v);else if(v instanceof Integer)editor.putInt(k,(Integer)v);else if(v instanceof Long)editor.putLong(k,(Long)v);else if(v instanceof org.json.JSONArray){Set<String> set=new HashSet<>();org.json.JSONArray a=(org.json.JSONArray)v;for(int i=0;i<a.length();i++)set.add(a.getString(i));editor.putStringSet(k,set);}else throw new IOException();}if(!editor.commit())throw new IOException();runOnUiThread(()->recreate());}catch(Exception e){runOnUiThread(()->status.setText("Ошибка восстановления"));}}).start()).setNegativeButton("Отмена",null).show();}
 void refreshPlaylist(){String url=prefs.getString("url_"+prefs.getString("activeSource",""),"");if(url.isEmpty()){Toast.makeText(this,"Для этого плейлиста нет адреса обновления",Toast.LENGTH_LONG).show();return;}load(url,true);}
 void autoRefreshSettings(){new AlertDialog.Builder(this).setTitle("Обновление при запуске").setSingleChoiceItems(new String[]{"Выключено","Каждые 6 часов","Каждые 12 часов","Каждые 24 часа"},prefs.getInt("refreshMode",0),(d,i)->{prefs.edit().putInt("refreshMode",i).apply();d.dismiss();checkRefresh();}).setNegativeButton("Закрыть",null).show();}
 void checkRefresh(){int mode=prefs.getInt("refreshMode",0);if(mode<1||mode>3)return;String key=prefs.getString("activeSource",""),url=prefs.getString("url_"+key,"");long interval=new long[]{0,21600000L,43200000L,86400000L}[mode];if(!url.isEmpty()&&System.currentTimeMillis()-prefs.getLong("updated_"+key,0)>interval)load(url,true);}
 final Handler reminderHandler=new Handler(Looper.getMainLooper());
 final Runnable reminderTick=new Runnable(){public void run(){checkReminders();checkScheduled();reminderHandler.postDelayed(this,15000);}};
 void addReminder(Channel ch,Epg.Programme p){if(p.start<=System.currentTimeMillis()){Toast.makeText(this,"Передача уже началась",Toast.LENGTH_SHORT).show();return;}try{org.json.JSONArray a=new org.json.JSONArray(prefs.getString("reminders","[]"));org.json.JSONObject o=new org.json.JSONObject();o.put("title",p.title);o.put("channel",ch.name);o.put("url",ch.url);o.put("start",p.start);a.put(o);prefs.edit().putString("reminders",a.toString()).apply();Toast.makeText(this,"Напоминание добавлено",Toast.LENGTH_SHORT).show();}catch(Exception e){status.setText("Ошибка напоминания");}}
 void reminders(){try{org.json.JSONArray a=new org.json.JSONArray(prefs.getString("reminders","[]"));String[] labels=new String[a.length()];java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("dd.MM HH:mm",Locale.getDefault());for(int i=0;i<a.length();i++){org.json.JSONObject o=a.getJSONObject(i);labels[i]=fmt.format(new Date(o.getLong("start")))+" • "+o.optString("title");}new AlertDialog.Builder(this).setTitle("Напоминания (выберите для удаления)").setItems(labels,(d,i)->new AlertDialog.Builder(this).setMessage("Удалить напоминание?").setPositiveButton("Удалить",(x,y)->{a.remove(i);prefs.edit().putString("reminders",a.toString()).apply();}).setNegativeButton("Отмена",null).show()).setNegativeButton("Закрыть",null).show();}catch(Exception e){status.setText("Ошибка списка напоминаний");}}
 void checkReminders(){try{org.json.JSONArray a=new org.json.JSONArray(prefs.getString("reminders","[]"));long now=System.currentTimeMillis();for(int i=a.length()-1;i>=0;i--){org.json.JSONObject o=a.getJSONObject(i);long start=o.getLong("start");if(start>now)continue;a.remove(i);if(now-start>300000)continue;String url=o.optString("url");new AlertDialog.Builder(this).setTitle(o.optString("title")).setMessage("Начинается передача • "+o.optString("channel")).setPositiveButton("Смотреть",(d,w)->{for(Channel ch:channels)if(ch.url.equals(url)){play(ch);return;}}).setNegativeButton("Закрыть",null).show();}prefs.edit().putString("reminders",a.toString()).apply();}catch(Exception ignored){}}
 @Override protected void onStart(){super.onStart();reminderHandler.post(reminderTick);}
 File activeScheduled;long scheduledEnd;
 void scheduleRecording(Channel ch,Epg.Programme p){if(locked(ch.group)){askPin(()->scheduleAllowed(ch,p));return;}scheduleAllowed(ch,p);}
 void scheduleAllowed(Channel ch,Epg.Programme p){if(p.end<=System.currentTimeMillis()){Toast.makeText(this,"Передача завершилась",Toast.LENGTH_SHORT).show();return;}try{org.json.JSONArray a=new org.json.JSONArray(prefs.getString("scheduled","[]"));for(int i=0;i<a.length();i++){org.json.JSONObject old=a.getJSONObject(i);if(p.start<old.getLong("end")&&p.end>old.getLong("start")){Toast.makeText(this,"Пересечение с другой записью",Toast.LENGTH_LONG).show();return;}}org.json.JSONObject o=new org.json.JSONObject();o.put("title",p.title);o.put("url",ch.url);o.put("start",p.start);o.put("end",p.end);a.put(o);prefs.edit().putString("scheduled",a.toString()).apply();Toast.makeText(this,"Запись запланирована (приложение должно быть открыто)",Toast.LENGTH_LONG).show();}catch(Exception e){status.setText("Ошибка расписания");}}
 void scheduledList(){try{org.json.JSONArray a=new org.json.JSONArray(prefs.getString("scheduled","[]"));String[] labels=new String[a.length()];java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("dd.MM HH:mm",Locale.getDefault());for(int i=0;i<a.length();i++){org.json.JSONObject o=a.getJSONObject(i);labels[i]=fmt.format(new Date(o.getLong("start")))+" • "+o.optString("title");}new AlertDialog.Builder(this).setTitle("Запланированные записи").setItems(labels,(d,i)->new AlertDialog.Builder(this).setMessage("Отменить запись?").setPositiveButton("Да",(x,y)->{a.remove(i);prefs.edit().putString("scheduled",a.toString()).apply();}).setNegativeButton("Нет",null).show()).setNegativeButton("Закрыть",null).show();}catch(Exception e){status.setText("Ошибка расписания");}}
 void checkScheduled(){long now=System.currentTimeMillis();if(activeScheduled!=null&&now>=scheduledEnd){recorder.stop();activeScheduled=null;}try{org.json.JSONArray a=new org.json.JSONArray(prefs.getString("scheduled","[]"));boolean changed=false;for(int i=a.length()-1;i>=0;i--){org.json.JSONObject o=a.getJSONObject(i);if(o.getLong("end")<=now){a.remove(i);changed=true;continue;}if(o.getLong("start")>now||recorder.worker!=null)continue;File file=new File(recordingDir(),now+".ts");if(recorder.start(o.getString("url"),file,()->runOnUiThread(()->{if(file.equals(activeScheduled))activeScheduled=null;if(!isDestroyed())status.setText(recordingResult(file));}))){activeScheduled=file;scheduledEnd=o.getLong("end");a.remove(i);changed=true;status.setText("Запись по расписанию • "+o.optString("title"));}}if(changed)prefs.edit().putString("scheduled",a.toString()).apply();}catch(Exception ignored){}}
 void programmeActions(Channel ch,Epg.Programme p){new AlertDialog.Builder(this).setTitle(p.title).setMessage(p.description).setPositiveButton("Смотреть / архив",(d,w)->{if(p.end<=System.currentTimeMillis())archive(ch,p);else play(ch);}).setNeutralButton("Действия",(d,w)->new AlertDialog.Builder(this).setItems(new String[]{"Напомнить","Запланировать запись"},(x,i)->{if(i==0)addReminder(ch,p);else scheduleRecording(ch,p);}).show()).setNegativeButton("Закрыть",null).show();}
 ExoPlayer createPlayer(){int mode=Math.max(0,Math.min(2,prefs.getInt("bufferMode",1)));int[] min={5000,15000,30000},max={15000,50000,90000},initial={1000,2000,4000},rebuffer={1500,3000,6000};androidx.media3.exoplayer.DefaultLoadControl control=new androidx.media3.exoplayer.DefaultLoadControl.Builder().setBufferDurationsMs(min[mode],max[mode],initial[mode],rebuffer[mode]).build();androidx.media3.exoplayer.DefaultRenderersFactory factory=new androidx.media3.exoplayer.DefaultRenderersFactory(this).setEnableDecoderFallback(prefs.getBoolean("decoderFallback",true));return new ExoPlayer.Builder(this,factory).setLoadControl(control).build();}
 void engineSettings(){new AlertDialog.Builder(this).setTitle("Настройки движка").setItems(new String[]{"Размер буфера","Резервный декодер","Возобновлять последний канал"},(d,i)->{if(i==0)new AlertDialog.Builder(this).setSingleChoiceItems(new String[]{"Малый (5–15 сек.)","Стандартный (15–50 сек.)","Большой (30–90 сек.)"},prefs.getInt("bufferMode",1),(x,j)->{prefs.edit().putInt("bufferMode",j).apply();x.dismiss();Toast.makeText(this,"Применится после перезапуска",Toast.LENGTH_LONG).show();}).show();else{String key=i==1?"decoderFallback":"resumeLast";boolean value=!prefs.getBoolean(key,i==1);prefs.edit().putBoolean(key,value).apply();Toast.makeText(this,value?"Включено":"Выключено",Toast.LENGTH_SHORT).show();}}).show();}
 void resumeLast(){if(!prefs.getBoolean("resumeLast",false))return;String url=prefs.getString("lastChannel","");for(Channel c:channels)if(c.url.equals(url)&&!locked(c.group)){play(c);return;}}
 void remember(Channel c){prefs.edit().putString("lastChannel",c.url).apply();try{org.json.JSONArray old=new org.json.JSONArray(prefs.getString("history","[]"));org.json.JSONArray next=new org.json.JSONArray();next.put(c.url);for(int i=0;i<old.length()&&next.length()<50;i++){String u=old.optString(i);if(!u.equals(c.url))next.put(u);}prefs.edit().putString("history",next.toString()).apply();}catch(Exception ignored){}}
 void history(){ArrayList<Channel> found=new ArrayList<>();ArrayList<String> names=new ArrayList<>();try{org.json.JSONArray a=new org.json.JSONArray(prefs.getString("history","[]"));for(int i=0;i<a.length();i++)for(Channel c:channels)if(c.url.equals(a.optString(i))){found.add(c);names.add(c.name);break;}}catch(Exception ignored){}new AlertDialog.Builder(this).setTitle("Недавние каналы").setItems(names.toArray(new String[0]),(d,i)->play(found.get(i))).setNegativeButton("Закрыть",null).show();}
 void groups(){TreeSet<String> gs=new TreeSet<>();for(Channel c:channels)gs.add(c.group);ArrayList<String> a=new ArrayList<>();a.add("Все группы");a.addAll(gs);new AlertDialog.Builder(this).setTitle("Группы").setItems(a.toArray(new String[0]),(d,i)->{group=i==0?"":a.get(i);render();}).show();}
 void voiceInput(boolean searchOnly){android.content.Intent i=new android.content.Intent(android.speech.RecognizerIntent.ACTION_RECOGNIZE_SPEECH);i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE_MODEL,android.speech.RecognizerIntent.LANGUAGE_MODEL_FREE_FORM);i.putExtra(android.speech.RecognizerIntent.EXTRA_LANGUAGE,"ru-RU");i.putExtra(android.speech.RecognizerIntent.EXTRA_PROMPT,searchOnly?"Название канала":"Скажите команду или название канала");try{startActivityForResult(i,searchOnly?502:501);}catch(android.content.ActivityNotFoundException e){EditText input=new EditText(this);new AlertDialog.Builder(this).setTitle("Голосовой сервис недоступен. Введите команду").setView(input).setPositiveButton("Выполнить",(d,w)->{if(searchOnly)voiceSearch(input.getText().toString());else voiceCommand(input.getText().toString());}).setNegativeButton("Отмена",null).show();}}
 void voiceSearch(String text){filter=text.trim();group="";onlyFav=false;render();if(fullscreen)toggleFullscreen();}
 void voiceCommand(String text){String q=text.toLowerCase(Locale.ROOT).trim().replaceAll("[.!?]+$","");switch(q){case "следующий канал":stepChannel(1);return;case "предыдущий канал":stepChannel(-1);return;case "пауза":player.pause();return;case "продолжить":player.play();return;case "телепрограмма":case "открой телепрограмму":gridGuide();return;case "избранное":onlyFav=true;render();if(fullscreen)toggleFullscreen();return;case "полный экран":if(!fullscreen)toggleFullscreen();return;case "список каналов":if(fullscreen)toggleFullscreen();return;case "фильмы":case "сериалы":vodMenu();return;case "меню":quickMenu();return;}q=q.replaceFirst("^(включи|открой|найди|покажи)\\s+","").replaceFirst("^канал\\s+","");if(q.isEmpty())return;for(Channel ch:channels)if(ch.name.equalsIgnoreCase(q)){play(ch);return;}voiceSearch(q);}
 void search(){EditText e=new EditText(this);e.setText(filter);new AlertDialog.Builder(this).setTitle("Поиск каналов").setView(e).setNeutralButton("Голосом",(d,w)->voiceInput(true)).setPositiveButton("Найти",(d,w)->{filter=e.getText().toString();render();}).setNegativeButton("Сбросить",(d,w)->{filter="";render();}).show();}
 void epgDialog(){EditText e=new EditText(this);e.setSingleLine();e.setText(prefs.getString("epgUrl",""));new AlertDialog.Builder(this).setTitle("XMLTV / XMLTV.GZ").setView(e).setPositiveButton("Загрузить",(d,w)->loadEpg(e.getText().toString().trim())).setNegativeButton("Отмена",null).show();}
 void loadEpg(String url){status.setText("Загрузка телепрограммы…");new Thread(()->{try{Epg result=Epg.load(url);runOnUiThread(()->{epg=result;render();prefs.edit().putString("epgUrl",url).apply();status.setText("EPG: "+epg.entries.size()+" каналов");});}catch(Exception e){runOnUiThread(()->status.setText("Ошибка загрузки EPG"));}}).start();}
 void gridGuide(){gridGuideAt(System.currentTimeMillis());} void gridGuideAt(long when){long now=System.currentTimeMillis();long start=when-when%1800000L,end=start+10800000L;int scale=dp(100);LinearLayout outer=new LinearLayout(this);outer.setOrientation(1);HorizontalScrollView horizontal=new HorizontalScrollView(this);LinearLayout table=new LinearLayout(this);table.setOrientation(1);horizontal.addView(table);LinearLayout header=new LinearLayout(this);TextView label=new TextView(this);label.setText("Каналы");header.addView(label,new LinearLayout.LayoutParams(dp(180),dp(42)));java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("HH:mm",Locale.getDefault());for(int i=0;i<6;i++){TextView t=new TextView(this);t.setText(fmt.format(new Date(start+i*1800000L)));header.addView(t,new LinearLayout.LayoutParams(scale,dp(42)));}table.addView(header);ScrollView scroll=new ScrollView(this);LinearLayout rows=new LinearLayout(this);rows.setOrientation(1);scroll.addView(rows);table.addView(scroll,new LinearLayout.LayoutParams(-1,dp(240)));int count=0;for(Channel ch:displayed){if(count++>=150)break;LinearLayout row=new LinearLayout(this);Button name=new Button(this);name.setText(ch.name);name.setAllCaps(false);name.setOnClickListener(v->play(ch));row.addView(name,new LinearLayout.LayoutParams(dp(180),dp(54)));android.widget.FrameLayout timeline=new android.widget.FrameLayout(this);row.addView(timeline,new LinearLayout.LayoutParams(scale*6,dp(54)));for(Epg.Programme p:epg.forChannel(ch.id)){long a=Math.max(start,p.start),b=Math.min(end,p.end);if(b<=a)continue;int left=(int)((a-start)*scale/1800000L),width=Math.max(1,(int)((b-a)*scale/1800000L));Button cell=new Button(this);cell.setAllCaps(false);cell.setText(p.title);cell.setTextSize(12);cell.setSingleLine(true);cell.setEllipsize(android.text.TextUtils.TruncateAt.END);android.widget.FrameLayout.LayoutParams lp=new android.widget.FrameLayout.LayoutParams(width,dp(54));lp.leftMargin=left;timeline.addView(cell,lp);cell.setOnClickListener(v->programmeActions(ch,p));}rows.addView(row);}outer.addView(horizontal);new AlertDialog.Builder(this).setTitle("Телепрограмма • "+new java.text.SimpleDateFormat("dd.MM HH:mm",Locale.getDefault()).format(new Date(start))).setView(outer).setPositiveButton("Закрыть",null).setNeutralButton("← 3 часа",(d,w)->gridGuideAt(Math.max(now-604800000L,start-10800000L))).setNegativeButton("3 часа →",(d,w)->gridGuideAt(Math.min(now+604800000L,start+10800000L))).show();}
 void guide(){if(current==null){Toast.makeText(this,"Выберите канал",Toast.LENGTH_SHORT).show();return;}ArrayList<Epg.Programme> items=new ArrayList<>(epg.forChannel(current.id));if(items.isEmpty()){new AlertDialog.Builder(this).setMessage("Нет программы для этого канала").setPositiveButton("OK",null).show();return;}java.text.SimpleDateFormat fmt=new java.text.SimpleDateFormat("dd.MM HH:mm",Locale.getDefault());ArrayList<String> labels=new ArrayList<>();for(Epg.Programme p:items)labels.add(fmt.format(new Date(p.start))+" — "+p.title);new AlertDialog.Builder(this).setTitle(current.name).setItems(labels.toArray(new String[0]),(d,i)->{if(current!=null)programmeActions(current,items.get(i));}).show();}
 void quickMenu(){new AlertDialog.Builder(this).setTitle("Vision IPTV Pro").setItems(new String[]{"Список каналов / полный экран","Телепрограмма","Группы","Поиск","Избранное","История","Настройки воспроизведения","Управление эфиром","Голосовое управление","Главное меню"},(d,i)->{switch(i){case 0:toggleFullscreen();break;case 1:gridGuide();break;case 2:groups();break;case 3:search();break;case 4:onlyFav=!onlyFav;render();if(fullscreen)toggleFullscreen();break;case 5:history();break;case 6:playbackSettings();break;case 7:timeshift();break;case 8:voiceInput(false);break;case 9:mainMenu();break;}}).show();}
 void toggleFullscreen(){fullscreen=!fullscreen;sidebar.setVisibility(fullscreen?View.GONE:View.VISIBLE);status.setVisibility(fullscreen?View.GONE:View.VISIBLE);getWindow().getDecorView().setSystemUiVisibility(fullscreen?5894:0);if(fullscreen)video.requestFocus();else list.requestFocus();}
 final Handler remoteHandler=new Handler(Looper.getMainLooper());String channelDigits="";final Runnable tuneNumber=()->{String digits=channelDigits;channelDigits="";try{int n=Integer.parseInt(digits);if(n>=1&&n<=channels.size())play(channels.get(n-1));else Toast.makeText(this,"Нет канала №"+n,Toast.LENGTH_SHORT).show();}catch(NumberFormatException ignored){}};
 void remoteSettings(){String[] keys={"Кнопка MENU","Красная кнопка","Зелёная кнопка","Жёлтая кнопка","Синяя кнопка","Вверх (эфир)","Вниз (эфир)","Влево (эфир)","Вправо (эфир)","OK (эфир)","GUIDE","CH+","CH−","Долгое OK (эфир)"};String[] actions={"Полный экран","Телепрограмма","Группы","Поиск","История","Пауза / продолжить","Избранное","Следующий канал","Предыдущий канал","Быстрое меню","Голосовое управление","Управление эфиром","Запись","Ничего"};new AlertDialog.Builder(this).setTitle("Настройка пульта").setItems(keys,(d,i)->new AlertDialog.Builder(this).setTitle(keys[i]).setSingleChoiceItems(actions,prefs.getInt("remote_"+i,remoteDefault(i)),(x,j)->{prefs.edit().putInt("remote_"+i,j).apply();x.dismiss();}).show()).show();}
 int remoteDefault(int i){return new int[]{0,1,2,3,4,7,8,0,1,9,1,7,8,10}[i];}
 void remoteAction(int index){switch(prefs.getInt("remote_"+index,remoteDefault(index))){case 0:toggleFullscreen();break;case 1:gridGuide();break;case 2:groups();break;case 3:search();break;case 4:history();break;case 5:if(player.isPlaying())player.pause();else player.play();break;case 6:onlyFav=!onlyFav;render();break;case 7:stepChannel(1);break;case 8:stepChannel(-1);break;case 9:quickMenu();break;case 10:voiceInput(false);break;case 11:timeshift();break;case 12:record();break;}}
 void stepChannel(int direction){if(channels.isEmpty())return;ArrayList<Channel> visible=new ArrayList<>();for(Channel c:channels){if(onlyFav&&!favorites.contains(c.url)||!group.isEmpty()&&!group.equals(c.group)||!c.name.toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT)))continue;visible.add(c);}if(visible.isEmpty())return;int i=visible.indexOf(current);play(visible.get(i<0?0:(i+direction+visible.size())%visible.size()));}
 boolean longOk=false;
 @Override public boolean dispatchKeyEvent(KeyEvent event){int key=event.getKeyCode();if(fullscreen&&(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER||key==KeyEvent.KEYCODE_DPAD_UP||key==KeyEvent.KEYCODE_DPAD_DOWN||key==KeyEvent.KEYCODE_DPAD_LEFT||key==KeyEvent.KEYCODE_DPAD_RIGHT)){if(key==KeyEvent.KEYCODE_DPAD_CENTER||key==KeyEvent.KEYCODE_ENTER){if(event.getAction()==KeyEvent.ACTION_DOWN){if(event.getRepeatCount()==0)longOk=false;else if(!longOk&&event.isLongPress()){longOk=true;remoteAction(13);}}else if(event.getAction()==KeyEvent.ACTION_UP&&!longOk&&!event.isCanceled())remoteAction(9);}else if(event.getAction()==KeyEvent.ACTION_DOWN&&event.getRepeatCount()==0){remoteAction(key==KeyEvent.KEYCODE_DPAD_UP?5:key==KeyEvent.KEYCODE_DPAD_DOWN?6:key==KeyEvent.KEYCODE_DPAD_LEFT?7:8);}return true;}return super.dispatchKeyEvent(event);}
 @Override public boolean onKeyDown(int key,KeyEvent event){if(key==KeyEvent.KEYCODE_CHANNEL_UP){remoteAction(11);return true;}if(key==KeyEvent.KEYCODE_CHANNEL_DOWN){remoteAction(12);return true;}if(key>=KeyEvent.KEYCODE_0&&key<=KeyEvent.KEYCODE_9){if(event.getRepeatCount()==0){if(channelDigits.length()>=5)channelDigits="";channelDigits+=Integer.toString(key-KeyEvent.KEYCODE_0);status.setText("Канал № "+channelDigits);remoteHandler.removeCallbacks(tuneNumber);remoteHandler.postDelayed(tuneNumber,900);}return true;}if(key==KeyEvent.KEYCODE_MENU){remoteAction(0);return true;}if(key>=KeyEvent.KEYCODE_PROG_RED&&key<=KeyEvent.KEYCODE_PROG_BLUE){remoteAction(key-KeyEvent.KEYCODE_PROG_RED+1);return true;}if(key==KeyEvent.KEYCODE_GUIDE){remoteAction(10);return true;}if(key==KeyEvent.KEYCODE_BACK&&fullscreen){toggleFullscreen();return true;}return super.onKeyDown(key,event);}
 @Override protected void onStop(){recorder.stop();activeScheduled=null;remoteHandler.removeCallbacks(tuneNumber);channelDigits="";reminderHandler.removeCallbacks(reminderTick);super.onStop();if(player!=null)player.pause();} @Override protected void onDestroy(){logos.close();recorder.stop();if(player!=null)player.release();super.onDestroy();}
